def main():
    base = os.path.abspath(sys.argv[1] if len(sys.argv) > 1 else os.getcwd())
    for rel, (executable, blob) in FILES.items():
        path = os.path.join(base, *rel.split('/'))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as fh:
            fh.write(zlib.decompress(base64.b64decode(''.join(blob))))
        if executable:
            os.chmod(path, os.stat(path).st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    print(f"Created {len(FILES)} files in {os.path.join(base, 'KeyFlow')}")

if __name__ == "__main__":
    main()
